        ("<span><strong>Núcleo de Distribución Uniforme del Calor:</strong> reparte el calor por toda la base, sin quemar y sin dejar la comida cruda por un lado.</span>", "<span><strong>Rdzeń równomiernego rozprowadzania ciepła:</strong> rozprowadza ciepło po całym dnie, bez przypalania i surowych miejsc.</span>"),
        ("<span><strong>Revestimiento antiadherente real:</strong> cocina con menos aceite y nada se pega, ni siquiera el huevo o el arroz.</span>", "<span><strong>Prawdziwa powłoka nieprzywierająca:</strong> gotuj z mniejszą ilością oleju — nic nie przywiera, nawet jajka czy ryż.</span>"),
        ("<span><strong>Tapas de vidrio templado:</strong> controla la cocción sin quitar la tapa y sin perder calor.</span>", "<span><strong>Szklane pokrywki:</strong> kontroluj gotowanie bez zdejmowania pokrywki i bez utraty ciepła.</span>"),
        ("<span><strong>Asas Comfort-Grip:</strong> agarre seguro y fresco al tacto, incluso cuando la olla lleva mucho tiempo al fuego.</span>", "<span><strong>Uchwyty Comfort-Grip:</strong> pewny, chłodny chwyt nawet gdy garnek stoi długo na kuchni.</span>"),
